def equal_under_rotation(grid1, grid2):
    """Compare the second grid against the first after 0°, 90°, 180° and 270° rotation."""

    # A trivial case applies without performing any rotation.
    if grid1 == grid2:
        return True

    # For later lookups, make a tuple of the grid.
    def grid_tuple(grid):
        return tuple(grid)

    # These four functions yield the rotated grids.
    def rotate_90(grid):
        return list(zip(*grid[::-1]))
    def rotate_180(grid):
        return [row[::-1] for row in grid[::-1]]
    def rotate_270(grid):
        return list(zip(*grid))[::-1]

    # For each candidate rotation, convert the rows and compare.
    return any(grid_tuple(rotated) == grid_tuple(grid2)
               for rotated, rot in [(rotate_90(grid1), 90),
                                    (rotate_180(grid1), 180),
                                    (rotate_270(grid1), 270)])

