def intersection_car_pass_count(events, green_duration):
    # Each phase lasts green_duration ticks, alternating starting with N/S at tick 0.
    # A car passes only if it arrives during the green phase of its direction.

    # Map each direction to the ticks when its light is green.
    # When a car arrives, tick % (green_duration * 2) determines the phase.
    # Rounds start with N/S, then E/W, then N/S again.
    def green_ticks(direction):
        phase = 'N/S' if direction in ('N', 'S') else 'E/W'
        return {
            'N/S': range(0, green_duration * 2, green_duration * 2),
            'E/W': range(green_duration, green_duration * 2, green_duration * 2),
        }[phase]

    # Two cars arrive at tick 0. Only events where the tick is in the direction's green range count.
    return sum(1 for tick, direction in events if tick in green_ticks(direction))
