def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    stops = []
    if not requests:
        return stops
    stopped_at_start = start_floor in requests
    if direction == 1:
        for floor in range(start_floor, top_floor + 1):
            if floor in requests:
                stops.append(floor)
    else:
