def light_switch_group(n, events):
    light = [False] * n
    for event in events:
        if event[0] == 'toggle':
            idx = event[1]
            if idx < 0 or idx >= n:
                continue
            light[idx] = not light[idx]
        elif event[0] == 'toggle_all':
            for i in range(n):
                light[i] = not light[i]
        elif event[0] == 'reset':
            for i in range(n):
                light[i] = False
