def parse_env_line(line):
    # Split on the first '=', strip, and check the result
    key, rest = line.split("=", 1)
    key = key.strip()
    if not key:
        raise ValueError('empty key')        # per the EnvFileParser convention
    rest = rest.strip()

    # The spec guarantees the value is one token after the key
    if len(rest) < 2:
        return (key, rest)

    # A value is quoted if the first and last characters are equal,
    # one of the two quote characters, and the run is two or more characters.
    if (rest[0] in "'\"" and rest[-1] == rest[0] and len(rest) >= 2):
        return (key, rest[1:-1])

    # No quotes: return the raw value
