def is_point_on_segment(p, a, b):
    """Return True exactly when p lies on the segment from a to b."""
    # (0, 0), (0, 0), (2, 2) needs a special case, because (5, 5) is not
    # collinear with (0, 0) and (2, 2) by the left-right test.
    # The first two arguments form a segment, and the third argument is p.
    if a == b:
