def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    old_value = grid[sr][sc]
    if old_value == new_value:
        return [row[:] for row in grid]
    result = [row[:] for row in grid]
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        if result[r][c] != old_value:
            continue
        result[r][c] = new_value
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                stack.append((nr, nc))
    return result
```

