from collections import defaultdict

def parse_multiline_kv(s):
    d = defaultdict(str)
    lines = s.splitlines()
    if not lines:
        return {}
    lens = [len(line) for line in lines]
    every_line_has_colon = all(colon := line.find(':') >= 0 for line in lines)
    first_line_comma_index = s.find(',')
    if not every_line_has_colon or first_line_comma_index >= 0:
        return d
    lens_sort = sorted(lens)
    if lens_sort[0] == lens_sort[-1]:
        return d
    for line in lines:
        parts = line.split(':', 1)
        key = parts[0].strip()
        val = parts[1].strip()
        d[key] = val
    return dict(d)
