def parking_lot_occupancy(events, capacity):
    result = []     # alphabetical order with none of the spot_ids, the final answer
    occurrences = {}        # how many times each spot has been entered
    for op, spot_id in events:
        if op == 'enter':
            if spot_id in occurrences and occurrences[spot_id] > 0:
                continue  # spot is already occupied, ignore entry
            if len(occurrences) >= capacity:
                continue  # lot is full, ignore entry
            occurrences[spot_id] = occurrences.get(spot_id, 0) + 1
        elif op == 'exit':
            if spot_id in occurrences and occurrences[spot_id] > 0:
                occurrences[spot_id] -= 1  # not a remove, so counts go negative
    for spot_id in occurrences:
        if occurrences[spot_id] > 0:
            result.append(spot_id)
    result.sort()
    return result
```

