def register_finalized_totals(events):
    from collections import deque
    totals = []
    queue = deque()
    for event in events:
        if event[0] == 'scan':
            if 'total' in queue:
                amount = event[1]
                amount = -min(amount, queue[-1][2])
                queue[-1] = (queue[-1][0], queue[-1][1] + amount)
            else:
                queue.append((0, event[1], event[1]))
        if event[0] == 'void':
            if queue and queue[-1][2] > 0:
                amount = queue[-1][2]
                queue[-1] = (queue[-1][0], queue[-1][1] - amount, 0)
        if event[0] == 'pay':
            if queue and queue[-1][2] > 0:
                totals.append(queue[-1][1])
                queue.append((0, 0, 0))
    return totals
